+/** Picks the language from an Accept-Language header (q-values, region tags), else the default. */
+export function pickLanguage(header, fallback = config.defaultLanguage) {
+  if (typeof header !== "string") return fallback;
+  const ranked = header
+    .split(",")
+    .map((part, index) => {
+      const [tag, ...params] = part.trim().split(";");
+      const q = params.map((p) => p.trim().match(/^q=(\d*\.?\d+)$/i)).find(Boolean);
+      return { lang: tag.trim().toLowerCase().split("-")[0], q: q ? Number(q[1]) : 1, index };
+    })
+    .filter((x) => x.q > 0 && LANGUAGES.includes(x.lang))
+    .sort((a, b) => b.q - a.q || a.index - b.index);
+  return ranked.length ? ranked[0].lang : fallback;
+}
